update player_pets set level=greatest(1,least(30,coalesce(level,1))),xp=greatest(0,coalesce(xp,0)),evolution_stage=pet_evolution_stage(greatest(1,least(30,coalesce(level,1))))where level is null or level not between 1 and 30 or xp is null or xp<0 or evolution_stage not in('baby','young','adult','ancestral');
create table if not exists pet_evolution_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id),player_pet_id uuid not null references player_pets(id),old_level int not null,new_level int not null,xp_before int not null,xp_spent int not null,xp_after int not null,fc_cost numeric not null,rarity text not null,old_stage text,new_stage text,idempotency_key text unique not null,created_at timestamptz not null default now());alter table pet_evolution_history enable row level security;revoke all on pet_evolution_history from anon,authenticated;
create or replace function pet_xp_required(v int)returns int language sql immutable as $$select round(250*power(greatest(1,v),1.35))::int$$;create or replace function pet_evolution_cost(v int,r text)returns numeric language sql immutable as $$select ceil((2500*power(greatest(1,v),1.45)*case normalize_pet_rarity(r)when'uncommon'then 1.25 when'rare'then 1.6 when'epic'then 2.2 when'legendary'then 3.2 else 1 end)/100)*100$$;
create table if not exists pet_action_idempotency(idempotency_key text primary key,user_id uuid not null references game_players(id),player_pet_id uuid not null references player_pets(id),action text not null,result jsonb,created_at timestamptz not null default now());alter table pet_action_idempotency enable row level security;revoke all on pet_action_idempotency from anon,authenticated;
create or replace function feed_pet_v2(p_telegram_id bigint,p_player_pet_id uuid,p_food int,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;pet player_pets%rowtype;available int;gain int;payload jsonb;begin if p_food not between 1 and 1000 or length(p_idempotency_key)<8 then raise exception'INVALID_FEED_REQUEST';end if;select id into u from game_players where telegram_id=p_telegram_id for update;select result into payload from pet_action_idempotency where idempotency_key=p_idempotency_key and user_id=u;if payload is not null then return payload;end if;select*into pet from player_pets where id=p_player_pet_id and user_id=u for update;if pet.id is null then raise exception'PET_NOT_OWNED';end if;if pet.level>=30 then raise exception'PET_MAX_LEVEL';end if;select quantity into available from player_pet_inventory where user_id=u and item_type='food'and item_id is null for update;if coalesce(available,0)<p_food then raise exception'NOT_ENOUGH_PET_FOOD';end if;update player_pet_inventory set quantity=quantity-p_food,updated_at=now()where user_id=u and item_type='food'and item_id is null;gain:=p_food*100;update player_pets set xp=least(2147483647,xp+gain),updated_at=now()where id=pet.id;payload:=get_pet_dashboard(p_telegram_id);insert into pet_action_idempotency values(p_idempotency_key,u,pet.id,'feed',payload,now());return payload;end$$;
create or replace function upgrade_pet_v2(p_telegram_id bigint,p_player_pet_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;pet player_pets%rowtype;needed int;cost numeric;next_stage text;payload jsonb;begin if length(p_idempotency_key)<8 then raise exception'INVALID_EVOLUTION_REQUEST';end if;select*into u from game_players where telegram_id=p_telegram_id for update;select result into payload from pet_action_idempotency where idempotency_key=p_idempotency_key and user_id=u.id;if payload is not null then return payload;end if;select*into pet from player_pets where id=p_player_pet_id and user_id=u.id for update;if pet.id is null then raise exception'PET_NOT_OWNED';end if;if pet.level>=30 then raise exception'PET_MAX_LEVEL';end if;needed:=pet_xp_required(pet.level);if pet.xp<needed then raise exception'PET_XP_REQUIRED';end if;cost:=pet_evolution_cost(pet.level,pet.rarity);if u.forge_coins<cost then raise exception'NOT_ENOUGH_FC';end if;next_stage:=pet_evolution_stage(pet.level+1);update game_players set forge_coins=forge_coins-cost,updated_at=now()where id=u.id;update player_pets set level=pet.level+1,xp=pet.xp-needed,evolution_stage=next_stage,updated_at=now()where id=pet.id;insert into pet_evolution_history(user_id,player_pet_id,old_level,new_level,xp_before,xp_spent,xp_after,fc_cost,rarity,old_stage,new_stage,idempotency_key)values(u.id,pet.id,pet.level,pet.level+1,pet.xp,needed,pet.xp-needed,cost,pet.rarity,pet.evolution_stage,next_stage,p_idempotency_key);payload:=get_pet_dashboard(p_telegram_id);insert into pet_action_idempotency values(p_idempotency_key,u.id,pet.id,'upgrade',payload,now());return payload;end$$;
revoke all on function feed_pet_v2(bigint,uuid,int,text),upgrade_pet_v2(bigint,uuid,text)from public,anon,authenticated;grant execute on function feed_pet_v2(bigint,uuid,int,text),upgrade_pet_v2(bigint,uuid,text)to service_role;
